package com.personal.jobagent.automation;
import com.fasterxml.jackson.databind.ObjectMapper; import com.personal.jobagent.common.UuidV7; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.time.Instant; import java.util.*;
@Repository public class AutomationPlanRepository { public record PlanRow(UUID id,UUID applicationId,String targetUrl,String status,Map<String,Object> plan,List<Object> result,boolean submitApproved,Instant heartbeatAt,Instant updatedAt){} private final JdbcTemplate db; private final ObjectMapper json; public AutomationPlanRepository(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;} public UUID create(UUID applicationId,UUID jobId,String targetUrl,String key,List<AutomationPlan.Step> steps){UUID id=UuidV7.generate();Map<String,Object> body=Map.of("applicationId",applicationId,"jobId",jobId,"targetUrl",targetUrl,"steps",steps,"safetyContract",AutomationPlan.SAFETY_CONTRACT);try{db.update("insert into automation_plans(id,application_id,target_url,plan,idempotency_key,created_at,updated_at) values(?,?,?,?::jsonb,?,now(),now()) on conflict(idempotency_key) do nothing",id,applicationId,targetUrl,json.writeValueAsString(body),key);}catch(Exception e){throw new IllegalStateException("Unable to persist automation plan",e);}return db.queryForObject("select id from automation_plans where idempotency_key=?",UUID.class,key);} public Optional<PlanRow> find(UUID id){return db.query("select id,application_id,target_url,status,plan,result,submit_approved,heartbeat_at,updated_at from automation_plans where id=?",(rs,n)->new PlanRow((UUID)rs.getObject(1),(UUID)rs.getObject(2),rs.getString(3),rs.getString(4),readMap(rs.getString(5)),readList(rs.getString(6)),rs.getBoolean(7),rs.getTimestamp(8)==null?null:rs.getTimestamp(8).toInstant(),rs.getTimestamp(9).toInstant()),id).stream().findFirst();} public boolean claim(UUID id){return db.update("update automation_plans set status='RUNNING',heartbeat_at=now(),updated_at=now() where id=? and status='PREPARED'",id)==1;} public boolean heartbeat(UUID id){return db.update("update automation_plans set heartbeat_at=now(),updated_at=now() where id=? and status='RUNNING'",id)==1;} public boolean transition(UUID id,String from,String to){return db.update("update automation_plans set status=?,updated_at=now() where id=? and status=?",to,id,from)==1;} public boolean approveSubmit(UUID id){return db.update("update automation_plans set submit_approved=true,status='RUNNING',updated_at=now() where id=? and status='AWAITING_SUBMIT_APPROVAL' and submit_approved=false",id)==1;} public boolean appendStep(UUID id,int index,String stepId,String status,Map<String,Object> result,String screenshot){try{String value=json.writeValueAsString(result);return db.update("insert into automation_steps(id,plan_id,step_key,step_index,status,result,screenshot_ref) values(?,?,?,?,?,?,?) on conflict(plan_id,step_key) do update set status=excluded.status,result=excluded.result,screenshot_ref=excluded.screenshot_ref,updated_at=now()",UuidV7.generate(),id,stepId,index,status,value,screenshot)>0;}catch(Exception e){throw new IllegalStateException(e);}} public int recoverStale(Instant cutoff){return db.update("update automation_plans set status='PREPARED',updated_at=now() where status='RUNNING' and heartbeat_at < ?",java.sql.Timestamp.from(cutoff));} public boolean recordWorkerEvent(String eventId,UUID planId,UUID applicationId,UUID jobId,String type,Map<String,Object> payload){try{return db.update("insert into worker_events(id,event_id,plan_id,application_id,job_id,event_type,payload,processed_at) values(?,?,?,?,?,?,?::jsonb,now()) on conflict(event_id) do nothing",UuidV7.generate(),eventId,planId,applicationId,jobId,type,json.writeValueAsString(payload))>0;}catch(Exception e){throw new IllegalStateException("Unable to persist worker event",e);}} private Map<String,Object> readMap(String s){try{return s==null?Map.of():json.readValue(s,Map.class);}catch(Exception e){return Map.of("corrupt",true);}} private List<Object> readList(String s){try{return s==null?List.of():json.readValue(s,List.class);}catch(Exception e){return List.of(Map.of("corrupt",true));}} }